<style>.itr-summary{display:grid;grid-template-columns:repeat(2,1fr);gap:20px;margin:28px 0}.itr-summary article{padding:24px;border:1px solid var(--line);border-radius:16px;background:var(--surface)}.itr-summary strong{display:block;font:400 40px var(--display);color:var(--gold-300)}.itr-summary span{font-size:14px;color:var(--muted)}.itr-activity{list-style:none;padding:0}.itr-activity li{padding:16px 0;border-bottom:1px solid var(--line)}.itr-activity p{margin:0 0 4px}.itr-activity small{color:var(--muted)}@media(max-width:600px){.itr-summary{grid-template-columns:1fr}}</style>
